package com.bn.aliagent.insight.radar; import static org.junit.jupiter.api.Assertions.*; import java.math.*; import java.util.*; import org.junit.jupiter.api.Test;
class AnomalyDetectorTest { private final AnomalyDetector detector=new AnomalyDetector();
 @Test void detectsAbsoluteThresholdBeforeTrend(){var result=detector.detect(new ThresholdRule("refund_rate",1,new BigDecimal("0.20"),new BigDecimal("1.50"),10,RiskLevel.HIGH),new BigDecimal("0.30"),20,List.of(new BigDecimal("0.10")));assertTrue(result.anomalous());assertTrue(result.reasons().contains("ABSOLUTE_THRESHOLD"));}
 @Test void usesSevenAndTwentyEightDaySamePeriodBaseline(){var result=detector.detect(new ThresholdRule("refund_rate",1,new BigDecimal("0.90"),new BigDecimal("1.50"),10,RiskLevel.HIGH),new BigDecimal("0.30"),20,List.of(new BigDecimal("0.10"),new BigDecimal("0.20"),new BigDecimal("0.10")));assertTrue(result.reasons().contains("TREND_7_28"));}
 @Test void refusesInsufficientSample(){var result=detector.detect(new ThresholdRule("refund_rate",1,new BigDecimal("0.20"),new BigDecimal("1.50"),10,RiskLevel.HIGH),new BigDecimal("0.30"),9,List.of(new BigDecimal("0.10")));assertTrue(result.insufficientSample());assertFalse(result.anomalous());}}
